window.renderAi4sCase=(t,href)=>{
 const picture=(name,zh,en,cls='')=>`<figure class="ai4s-image ${cls}"><img src="assets/ai4s/${name}.jpg" alt="${t(zh,en)}" ${name==='cover'?'fetchpriority="high"':'loading="lazy"'}></figure>`;
 const copy=(zh,en,bodyZh,bodyEn)=>`<section class="ai4s-copy"><h2>${t(zh,en)}</h2><div><p>${t(bodyZh,bodyEn)}</p></div></section>`;
 return `<article class="ai4s-case"><figure class="ai4s-image ai4s-new-hero"><img src="assets/ai4s/hero-display-v2.jpg" alt="${t('AI4S人工智能赋能科学研究研讨会主视觉展示','AI4S symposium key visual display')}" width="1536" height="1024" fetchpriority="high"></figure><section class="ai4s-project-intro"><div class="ai4s-project-intro-copy"><p>${t('为推动科研范式和产业创新的系统性变革，世界互联网大会人工智能专业委员会举办了AI4S（AI for Science）专题研讨会。基于本次研讨会的宗旨，设计需在视觉上精准<strong>平衡人工智能科技未来感与科学研究的学术严谨性</strong>。同时，需着重<strong>突出AI4S（AI for Science）主题</strong>，体现人工智能对科学研究的赋能，并通过中英文双语展示强化国际化传播属性，确保信息传达的清晰性与专业性。','To advance systemic change in research paradigms and industrial innovation, the World Internet Conference’s AI Committee held a symposium on AI4S (AI for Science). Its visual design needed to <strong>balance the futuristic character of AI technology with the academic rigour of scientific research</strong>. It also needed to <strong>highlight AI4S (AI for Science)</strong>, express AI’s role in enabling research, and support international communication through clear, professional Chinese–English presentation.')}</p></div><div class="ai4s-project-intro-meta"><span>${t('项目 / 品牌：世界互联网大会人工智能专业委员会','Project: World Internet Conference AI Committee')}</span><span>${t('年份：2025','Year: 2025')}</span><span>${t('服务：会议主视觉 / 视觉系统 / 应用延展','Services: Key visual / Visual system / Applications')}</span></div></section>
 ${picture('concepts','人工智能、赋能与科学研究的视觉概念','Visual concepts: AI, empowerment and scientific research')}
 <section class="ai4s-centered-copy"><h2>品牌主视觉</h2><p>主视觉从图形、字体、颜色、排版几个方面来设计，以几何图形与精密算法线条构建，字体选用科技感无衬线体强化严谨性，冷调科技蓝与亮色渐变碰撞象征突破与包容。</p></section><section class="ai4s-centered-copy"><h2>图形元素</h2><div class="ai4s-motif-points"><p>①　严谨性、未来感、交叉验证</p><p>②　能量传递、算法</p><p>③　用代表算法的线条和几何图形构成了AI4S核心图形，叠加的彩色渐变图形是一种涌现，寓意着突破和包容。</p></div></section>
 ${picture('motif','浅蓝色几何图形延展','Light-blue geometric motif')}${picture('lettering','线条节奏与 AI4S 字母图形','Line patterns and AI4S lettering')}
 <div class="ai4s-palette-section">${copy('色彩与字体','Colour & typography','深蓝色建立理性、可靠的学术气质，浅蓝色与柔和渐变带来轻盈、开放的科技感。中文与英文字体共同服务于双语信息层级，保持清晰、统一的阅读体验。','Deep blue anchors the identity with a composed academic tone, while light blue and soft gradients introduce openness and a contemporary technology feel. Chinese and English typography share a clear, consistent information hierarchy.')}
 ${picture('palette','品牌色彩与字体规范','Brand colour palette and typography')}</div>${copy('品牌应用','Brand applications','视觉系统延展至会议资料、展示物料、网页、工作证和麦克风等触点，在不同媒介中保持一致的识别与信息层级。','The system extends across conference materials, displays, web pages, badges and microphones, maintaining a consistent identity and information hierarchy across different formats.')}
 <section class="ai4s-phone-section"><p class="ai4s-phone-hint">${t('在手机内上下滑动，查看完整长图 ↓','Scroll inside the phone to explore the full image ↓')}</p><div class="ai4s-flat-phone"><div class="ai4s-phone-speaker" aria-hidden="true"></div><div class="ai4s-phone-screen" tabindex="0" role="region" aria-label="${t('可上下滑动的会议活动长图','Scrollable symposium information')}"><img src="assets/ai4s/conference-long.png" alt="${t('AI4S研讨会介绍、会议信息、组织机构与议程长图','AI4S symposium introduction, information, organisers and agenda')}" loading="eager"></div></div></section><figure class="ai4s-image ai4s-design-application" style="width:100%;margin:55px 0 0"><img src="assets/ai4s/design-application-board7.png" alt="${t('AI4S手机海报与现场签到处应用展示','AI4S mobile poster and check-in display applications')}" width="2800" height="1809" loading="lazy"></figure>
 ${picture('applications','会议物料与数字媒介应用','Conference collateral and digital applications')}
 <figure class="ai4s-image ai4s-macbook-display" style="width:100%;margin:0"><img src="assets/ai4s/macbook-display.jpg" alt="${t('AI4S研讨会官网传播页面MacBook展示','AI4S symposium website displayed on a MacBook')}" width="2048" height="1365" loading="lazy"></figure>
 <section class="ai4s-copy"><h2>${t('会议现场','At the conference')}</h2></section>
 ${picture('conference','研讨会现场与嘉宾交流','Symposium proceedings and panel discussions')}</article><section class="next-project"><a href="${href('work')}">↖ ${t('返回全部案例','Back to all projects')}</a><a href="${href('project','&id=01')}"><span>${t('下一个项目','Next project')}</span><strong>${t('节日节点传播','Seasonal communication')} ↗</strong></a></section>`;
};
